// 작성자 송예찬 · 의사코드: 사용자 포드 Transform을 보존하고 생활 가구·양면 배식구를 반입한다.
// 코딩: 기하 배치와 정적 충돌만 구성하며 게임 로직을 추가하지 않는다.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class HabitatSession {
 public const string R="Assets/Afrer_Seconds/";
 public static string W=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../tmp/Habitat_20261103"));
 public static Transform[] All()=>SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
 public static Transform Room=>All().First(t=>t.name=="Room01_Isolation");
 public static Transform Pod=>Room.Find("ObservationPod");
 public static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;
 public static Bounds B(GameObject g){var rr=g.GetComponentsInChildren<Renderer>(true).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();if(rr.Length==0)throw new Exception("No active Renderer "+g.name);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
 static void GuardContext(){if(EditorApplication.isPlaying||!SceneManager.GetActiveScene().path.EndsWith("Level_B5_Isolation.unity"))throw new Exception("B5 edit mode required");if((Pod.localScale-new Vector3(3,2,3)).sqrMagnitude>.00001f)throw new Exception("User changed pod scale during work; inspect before applying");}
 public static Transform Group(Transform parent,string name){var t=parent.Find(name);if(t)return t;var g=new GameObject(name);g.transform.SetParent(parent,false);return g.transform;}
 public static string ImportModel(string source,string destination){Directory.CreateDirectory(Path.GetDirectoryName(destination));File.Copy(source,destination,true);AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var i=(ModelImporter)AssetImporter.GetAtPath(destination);i.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;i.materialLocation=ModelImporterMaterialLocation.InPrefab;i.importAnimation=false;i.importCameras=false;i.importLights=false;i.importNormals=ModelImporterNormals.Import;i.importTangents=ModelImporterTangents.CalculateMikk;i.meshCompression=ModelImporterMeshCompression.Off;i.addCollider=false;i.SaveAndReimport();return destination;}
 static Dictionary<string,Material> LivingMaterials(JObject config){var dict=new Dictionary<string,Material>();string folder=R+"05.Model/Props/B5/Materials";Directory.CreateDirectory(folder);AssetDatabase.Refresh();foreach(var p in config.Properties()){var c=p.Value;string path=folder+"/"+p.Name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);bool fresh=!mat;if(fresh)mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.name=p.Name;var color=c["baseColor"].ToObject<float[]>();mat.SetColor("_BaseColor",new Color(color[0],color[1],color[2],color[3]));mat.SetFloat("_Metallic",(float)c["metallic"]);mat.SetFloat("_Smoothness",(float)c["smoothness"]);float em=(float)c["emission"];if(em>0){mat.SetColor("_EmissionColor",new Color(color[0],color[1],color[2])*em);mat.EnableKeyword("_EMISSION");}if(fresh)AssetDatabase.CreateAsset(mat,path);else EditorUtility.SetDirty(mat);dict.Add(p.Name,mat);}return dict;}
 public static void Assign(GameObject g,Dictionary<string,Material> materials){foreach(var r in g.GetComponentsInChildren<Renderer>(true)){r.sharedMaterials=r.sharedMaterials.Select(m=>{var key=materials.Keys.FirstOrDefault(k=>m&&m.name.StartsWith(k));if(key==null)throw new Exception("Unmapped material on "+r.name+": "+(m?m.name:"null"));return materials[key];}).ToArray();r.shadowCastingMode=r.sharedMaterials.Any(m=>m.name.Contains("Glass"))?ShadowCastingMode.Off:ShadowCastingMode.On;}}
 public static string ImportLiving(){var manifest=JArray.Parse(File.ReadAllText(Path.Combine(W,"LivingModels/manifest.json")));var mats=LivingMaterials((JObject)manifest[0]["materials"]);var results=new List<object>();foreach(JObject a in manifest){string name=(string)a["name"],target=R+"05.Model/Props/B5/"+name;ImportModel((string)a["fbx"],target+".fbx");var go=new GameObject(name+"_VisualOnly");var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(target+".fbx"));model.transform.SetParent(go.transform,false);Assign(go,mats);var marker=go.GetComponentsInChildren<Transform>(true).First(t=>t.name==(string)a["frontMarker"]);var dir=marker.position-go.transform.position;dir.y=0;model.transform.localRotation=Quaternion.Euler(0,Vector3.SignedAngle(dir,Vector3.back,Vector3.up),0)*model.transform.localRotation;var b=B(go);model.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z);PrefabUtility.SaveAsPrefabAsset(go,target+".prefab");results.Add(new{name=name,prefab=target+".prefab",bounds=V(B(go).size),triangles=(int)a["triangles"]});UnityEngine.Object.DestroyImmediate(go);a["fbx"]=target+".fbx";a["prefab"]=target+".prefab";}File.WriteAllText(R+"06.Data/AssetSources/SubjectHabitat_LivingModels.json",manifest.ToString());AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(W,"living_import_facts.json"),JsonConvert.SerializeObject(results,Formatting.Indented));return "5 living models imported at human scale";}
 public static string InstallHatch(){GuardContext();if(Pod.Find("HabitatShell_Visual"))throw new Exception("Hatch already installed");var m=JObject.Parse(File.ReadAllText(Path.Combine(W,"Hatch/manifest.json")));string dir=R+"05.Model/Environment/B5/";var mats=AssetDatabase.FindAssets("t:Material",new[]{dir+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).Where(a=>a.name.StartsWith("OP_")).ToDictionary(a=>a.name,a=>a);
 var paths=new Dictionary<string,string>();foreach(var p in ((JObject)m["exports"]).Properties()){string target=dir+Path.GetFileName((string)p.Value);ImportModel((string)p.Value,target);paths.Add(p.Name,target);}
 foreach(var old in Pod.Cast<Transform>().ToArray()){foreach(var r in old.GetComponentsInChildren<Renderer>(true))r.enabled=false;foreach(var c in old.GetComponentsInChildren<Collider>(true))c.enabled=false;}
 var instances=new Dictionary<string,GameObject>();foreach(var a in paths){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(a.Value),SceneManager.GetActiveScene());if(a.Key.StartsWith("hatch"))PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);g.name=a.Key=="shellVisual"?"HabitatShell_Visual":a.Key=="shellCollision"?"HabitatShell_Collision":a.Key=="hatchVisual"?"DualFoodHatch_Visual":"DualFoodHatch_Collision";g.transform.SetParent(Pod,false);g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.Euler(0,180,0);g.transform.localScale=Vector3.one;if(a.Key.EndsWith("Visual"))Assign(g,mats);else{foreach(var r in g.GetComponentsInChildren<Renderer>(true))r.enabled=false;foreach(var mf in g.GetComponentsInChildren<MeshFilter>(true)){var c=mf.gameObject.AddComponent<MeshCollider>();c.sharedMesh=mf.sharedMesh;c.convex=false;}}instances[a.Key]=g;}
 // Matching leaf Collider objects inherit the visible door pivot's motion.
 var visual=instances["hatchVisual"];var collision=instances["hatchCollision"];foreach(string side in new[]{"Exterior","Interior"}){var pivot=visual.GetComponentsInChildren<Transform>().First(t=>t.name=="DualFoodHatch_Door"+side+"_Pivot");var leaf=collision.GetComponentsInChildren<MeshFilter>().First(f=>f.name.Contains("Door"+side));leaf.transform.SetParent(pivot,true);}
 m["exports"]=JObject.FromObject(paths);File.WriteAllText(R+"06.Data/AssetSources/SubjectHabitat_DualFoodHatch.json",m.ToString());AssetDatabase.SaveAssets();Physics.SyncTransforms();return "Hollow transfer hatch installed; two matching doors and Collider leaves wired";}
 public static void SetBottom(GameObject g,Vector3 bottom,float yaw){g.transform.rotation=Quaternion.Euler(0,yaw,0);var b=B(g);g.transform.position+=bottom-new Vector3(b.center.x,b.min.y,b.center.z);}
 public static GameObject Place(string prefab,string name,Transform group,Vector3 pos,float yaw,float scale=1){if(group.Find(name))throw new Exception("Duplicate "+name);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(prefab),SceneManager.GetActiveScene());g.name=name;g.transform.SetParent(group,false);g.transform.localScale=Vector3.one*scale;SetBottom(g,pos,yaw);return g;}
 public static void StaticPhysics(GameObject go){foreach(var mf in go.GetComponentsInChildren<MeshFilter>(true)){var r=mf.GetComponent<Renderer>();if(!r||!r.enabled||mf.GetComponent<Collider>())continue;var c=mf.gameObject.AddComponent<MeshCollider>();c.sharedMesh=mf.sharedMesh;c.convex=false;}}
 static float TopSurface(GameObject go,Vector3 location,float fallback){Physics.SyncTransforms();var hits=Physics.RaycastAll(new Vector3(location.x,3,location.z),Vector3.down,4).Where(h=>h.transform.IsChildOf(go.transform)).OrderBy(h=>h.distance).ToArray();return hits.Length>0?hits[0].point.y:fallback;}
 static void FloorCollider(){var vertices=new List<Vector3>();var triangles=new List<int>();int n=96;float radius=3.89f;for(int y=0;y<2;y++)for(int i=0;i<n;i++){float a=2*Mathf.PI*i/n;vertices.Add(new Vector3(Mathf.Cos(a)*radius,y==0?.22f:.28f,Mathf.Sin(a)*radius));}vertices.Add(new Vector3(0,.22f,0));vertices.Add(new Vector3(0,.28f,0));for(int i=0;i<n;i++){int j=(i+1)%n;triangles.AddRange(new[]{i,j,n+j,i,n+j,n+i,2*n,j,i,2*n+1,n+i,n+j});}for(int i=0;i<triangles.Count;i+=3){int a=triangles[i];triangles[i]=triangles[i+2];triangles[i+2]=a;}var mesh=new Mesh{name="SubjectHabitat_FloorCollision"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();string path=R+"05.Model/Environment/B5/SubjectHabitat_FloorCollision.asset";AssetDatabase.CreateAsset(mesh,path);var g=new GameObject("HabitatFloor_Collision");g.transform.SetParent(Room,false);g.transform.localPosition=new Vector3(0,0,Pod.localPosition.z);g.AddComponent<MeshCollider>().sharedMesh=mesh;g.transform.SetParent(Pod,true);}
 public static string Dress(){GuardContext();if(Room.Find("Habitat_LivingArea"))throw new Exception("Living area already created");var group=Group(Room,"Habitat_LivingArea");var staff=Group(Room,"Habitat_StaffEquipment");var bunk=All().First(t=>t.name.StartsWith("P01_IsolationBunk"));SetBottom(bunk.gameObject,new Vector3(-2.2f,.28f,12.1f),0);StaticPhysics(bunk.gameObject);
 var desk=Place(R+"05.Model/Props/B5/LivingDesk.prefab","LivingDesk",group,new Vector3(2.2f,.28f,8.85f),180);StaticPhysics(desk);var surface=desk.GetComponentsInChildren<Transform>(true).First(t=>t.name.StartsWith("HM_MealSurface"));Place(R+"05.Model/Props/B5/MealTraySet.prefab","MealTray_DailyRation",group,surface.position,180);
 float bedTop=TopSurface(bunk.gameObject,new Vector3(-2.2f,0,12.1f),.78f);Place(R+"05.Model/Props/B5/BedLinen.prefab","Pillow_And_FoldedBlanket",group,new Vector3(-2.2f,bedTop+.003f,12.1f),0);
 var hygiene=Place(R+"05.Model/Props/B5/HygieneStation.prefab","HygieneCorner",group,new Vector3(-2.45f,.28f,8.95f),-90);StaticPhysics(hygiene);
 var monitor=Place(R+"05.Model/Props/B5/TestMonitorStand.prefab","Subject_TestMonitor",group,new Vector3(-1.4f,.28f,12.4f),-35);StaticPhysics(monitor);
 var locker=Place(R+"05.Model/Props/Common/P04_RecordsCabinet.prefab","PersonalLinen_Locker",group,new Vector3(2.75f,.28f,11.9f),90);StaticPhysics(locker);
 var waste=Place(R+"05.Model/Props/Common/P07_SealedWasteBin.prefab","Hygiene_WasteBin",group,new Vector3(-3.08f,.28f,10.2f),-90);StaticPhysics(waste);
 var bench=Place(R+"05.Model/Props/Common/Props_LaboratoryWorkbench.prefab","Staff_SamplePreparation",staff,new Vector3(5.3f,0,12),90,1.8f);StaticPhysics(bench);
 var trolley=Place(R+"05.Model/Props/Common/P09_LaboratoryTrolley.prefab","Staff_MedicalTrolley",staff,new Vector3(-4.9f,0,12.8f),90);StaticPhysics(trolley);float trayTop=TopSurface(trolley,new Vector3(-4.9f,0,12.8f),.78f);Place(R+"05.Model/Props/Common/P05_SampleCanister.prefab","Staff_SampleCanister",staff,new Vector3(-4.9f,trayTop+.003f,12.8f),0);
 var console=All().First(t=>t.parent&&t.parent.name=="VARCO_V002_Visuals"&&P(t).Contains("Room01_Isolation"));SetBottom(console.gameObject,new Vector3(-5.68f,1.15f,9.5f),-90);
 var label=All().FirstOrDefault(t=>t.name=="Sign_S-03");if(label)label.position=new Vector3(.9f,.65f,6.32f);
 // Small legacy crate trim must follow its new visible shell rather than hover over the old cube.
 foreach(var actor in Room.Find("Actors").Cast<Transform>().Where(t=>t.name.StartsWith("LightBox"))){var old=actor.Find("CyanBand_VisualOnly");if(old)foreach(var r in old.GetComponentsInChildren<Renderer>())r.enabled=false;old=actor.Find("BlackLatch_VisualOnly");if(old)foreach(var r in old.GetComponentsInChildren<Renderer>())r.enabled=false;}
 FloorCollider();var cc=All().SelectMany(t=>t.GetComponents<CharacterController>()).Single();var pos=cc.transform.position;float oldFoot=cc.transform.TransformPoint(cc.center).y-cc.height*.5f;pos.y+=.285f-oldFoot;cc.transform.position=pos;
 var guard=All().First(t=>t.name.StartsWith("Guard_A_"));var gb=B(guard.gameObject);float front=Pod.position.z-3.99f;if(gb.max.z>front-.7f){guard.position=new Vector3(0,guard.position.y,4.9f);}Physics.SyncTransforms();return "Sleeping, meals, hygiene, storage and testing areas dressed; guard outside glass";}
 public static void Render(string file,Vector3 pos,Vector3 target,bool overhead=false){var hidden=new List<Renderer>();foreach(var cc in All().SelectMany(t=>t.GetComponents<CharacterController>()))foreach(var r in cc.GetComponentsInChildren<Renderer>(true))if(r.enabled){r.enabled=false;hidden.Add(r);}if(overhead)foreach(var t in All().Where(t=>P(t).Contains("Room01_Isolation")&&(t.name.Contains("Ceiling")||t.name.Contains("HabitatShell_Visual"))))foreach(var r in t.GetComponentsInChildren<Renderer>(true))if(r.enabled){r.enabled=false;hidden.Add(r);}var g=new GameObject("Temporary_HabitatReviewCamera");g.hideFlags=HideFlags.HideAndDontSave;var c=g.AddComponent<Camera>();c.enabled=false;c.transform.position=pos;c.transform.LookAt(target);c.fieldOfView=65;c.nearClipPlane=.04f;c.farClipPlane=100;c.useOcclusionCulling=false;c.allowHDR=true;c.GetUniversalAdditionalCameraData().renderPostProcessing=true;var rt=new RenderTexture(1600,1000,24);var previous=RenderTexture.active;
 try{c.targetTexture=rt;c.Render();c.Render();c.Render();RenderTexture.active=rt;var image=new Texture2D(1600,1000,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,1000),0,0);image.Apply();File.WriteAllBytes(Path.Combine(W,file),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{c.targetTexture=null;RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);foreach(var r in hidden)r.enabled=true;}}
 public static string ReviewRenders(){Render("habitat_exterior.png",new Vector3(5.1f,2.4f,4.3f),new Vector3(0,1.5f,10.3f));Render("habitat_sleeping.png",new Vector3(.65f,1.85f,10.2f),new Vector3(-2.05f,1,12.15f));Render("habitat_meal_hygiene.png",new Vector3(.3f,1.85f,12.0f),new Vector3(.3f,1,8.8f));Render("hatch_inside.png",new Vector3(.4f,1.35f,7.7f),new Vector3(0,1.05f,6.345f));Render("hatch_outside.png",new Vector3(.5f,1.35f,4.9f),new Vector3(0,1.05f,6.345f));Render("habitat_overview.png",new Vector3(14,16,21),new Vector3(0,0,9),true);return "Habitat exterior/interior/hatch review views captured";}
 public static string Save(){GuardContext();var p=Pod.position;var r=Pod.rotation;var s=Pod.localScale;var copy=UnityEngine.Object.Instantiate(Pod.gameObject);copy.name="ObservationPod_Habitat";copy.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);string prefab=R+"04.Prefabs/Environment/ObservationPod_Habitat.prefab";PrefabUtility.SaveAsPrefabAsset(copy,prefab);UnityEngine.Object.DestroyImmediate(copy);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(W,"habitat_scene_facts.json"),JsonConvert.SerializeObject(new{scene=SceneManager.GetActiveScene().path,podPosition=V(p),podScale=V(s),roomHeight=7.2,roomSize=new[]{12,14},prefab=prefab,interiorFloor=.28,guardPosition=V(All().First(t=>t.name.StartsWith("Guard_A_")).position),living=Room.Find("Habitat_LivingArea").Cast<Transform>().Select(t=>new{t.name,position=V(t.position),center=V(B(t.gameObject).center),size=V(B(t.gameObject).size)}).ToArray()},Formatting.Indented));return "B5 habitat saved with the user-authored pod scale";}
}
// 주석: 포드 크기를 일반 사람 크기 가구에 곱하지 않는다. 양면 문은 기하·피벗 구성까지이며 입력 동작 코드를 추가하지 않는다.
